            // CA Additions to federal taxable income
            double additions = 0.0;

            // Add back IRC 199A deduction (CA does not conform)
            // additions += result.section_199a_deduction;

            // Add back federal interest (taxable to CA)
            // additions += revenue.federal_bond_interest;

            // Add back bonus depreciation (CA partially decouples)
            // CA allows only portion of federal bonus depreciation

            apportionment.state_additions = additions;

            // CA Subtractions from federal taxable income
            double subtractions = 0.0;

            // Subtract CA municipal bond interest (already in federal income but CA-exempt)
            // subtractions += revenue.ca_municipal_interest;

            // Subtract CA NOL deduction (different rules than federal)
            // subtractions += result.ca_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // Calculate CA income tax at 8.84%
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Apply minimum franchise tax ($800)
            apportionment.state_tax =
              Math.max(result.ca_minimum_franchise_tax, apportionment.state_tax);

            // Subtract CA credits
            apportionment.state_tax =
              Math.max(result.ca_minimum_franchise_tax,
                       apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

// No income but still owe minimum franchise tax
apportionment.state_tax = result.ca_minimum_franchise_tax;
apportionment.state_refund_or_owed =
  apportionment.state_payments - apportionment.state_tax;

